with cleaned as (select id, order_id, method, paid_at, cast(paid_at as date) paid_at_day, date_format(paid_at, 'yyyy-MM') paid_at_label from payments where method = 'bank_transfer') select *, row_number() over (partition by method order by paid_at_day, id) row_seq, row_number() over (partition by order_id order by paid_at desc, id) row_seq_2, last_value(method, true) over (partition by order_id order by paid_at_day, id rows between unbounded preceding and current row) last_known_method, last_value(method) ignore nulls over (partition by order_id, method order by paid_at_day, id rows between unbounded preceding and current row) last_known_method_2 from cleaned;
